//! Independent revision35 integration regressions. Controlled fixture, not balance certification.
use corpse_core::{Command,Field,Run,engine,population,portals,portals_generation::PortalPair,projectiles,vision,movement::Point,temporal::Engine,replay::{ReplayRecord,ReplaySession},dreamwalking as dream,half_here};
use std::sync::Arc;
fn room()->Run {
 let mut r:Run=serde_json::from_str(include_str!("../../../fixtures/avatar-room-v1.json")).unwrap();
 r.simulation_revision=35.0.into();r.inventory.clear();r.offers.clear();r.history.clear();r.replay.clear();r.future=None;r.phase=Field::Missing;r.haste_snapshot=Field::Missing;r.log.clear();r.log_kinds=Field::Missing;r.log_archive=Field::Missing;
 r.player.abilities.clear();r.player.active.clear();r.player.conditions.clear();r.player.x=8.;r.player.y=8.;r.player.hp=100.;r.player.max_hp=100.;r.player.energy=1000.;r.player.stats.max_energy=1000.;r.player.stats.accuracy=10000.;r.player.stats.offense=20.;r.next_id=1000.;r.rng=1.;
 let mut f=r.floors[0].as_ref().clone();f.environment=Field::Missing;f.vents=Field::Missing;f.permanent_fire=Field::Missing;f.godbeast_event=Field::Missing;f.godbeast=false;f.doors=Field::Missing;f.light_sources=Field::Missing;f.blood=Field::Missing;f.roots=Field::Missing;f.fungal_roots=Field::Missing;f.razorleaves=Field::Missing;f.grates=Field::Missing;f.portals=Field::Missing;
 let(w,h)=(f.width(),f.height());for y in 1..h-1{for x in 1..w-1{f.tiles[y*w+x]="floor".into()}}f.tiles[w+1]="up".into();f.tiles[(h-2)*w+w-2]="down".into();f.lights.fill(1.);
 r.floors.clear();r.actors.clear();r.ground.clear();for depth in 1..=10{let mut floor=f.clone();floor.depth=depth as f64;r.floors.push(Arc::new(floor));r.actors.insert(depth.to_string(),Arc::new(vec![]));r.ground.insert(depth.to_string(),Arc::new(vec![]));}r.depth=10.;
 pair(&mut r,(9,8),(40,15));r
}
fn pair(r:&mut Run,a:(usize,usize),b:(usize,usize)){let f=r.floor_mut().unwrap();let w=f.width();f.portals=vec![PortalPair{a:a.1*w+a.0,b:b.1*w+b.0,color_index:0}].into();}
fn rat(r:&mut Run,x:f64,y:f64,ally:bool)->f64 {let id=r.next_id;r.next_id+=1.;let mut a=population::create_actor_revision("rat",id,x,y,false,35.).unwrap();a.state=if ally{"ally"}else{"sleeping"}.into();a.hp=100.;a.max_hp=100.;a.stats.dodge=-1000.;a.stats.defense=0.;a.stats.dr=0.;r.actors_at_mut(10.).push(a);id}
fn wall(r:&mut Run,x:usize,y:usize){let f=r.floor_mut().unwrap();let w=f.width();f.tiles[y*w+x]="wall".into();}
fn divider(r:&mut Run){for y in 1..28{wall(r,20,y)}}
fn ability(id:&str)->Command{Command::Ability{id:id.into(),target:Field::Missing,x:Field::Missing,y:Field::Missing}}
#[test]fn empty_entry_is_one_turn_then_leaving_does_not_bounce(){let mut e=Engine::new(room()).unwrap();let tick=e.run.tick;assert!(e.dispatch(&Command::Move{dx:1.,dy:0.}).unwrap().took_turn);assert_eq!((e.run.player.x,e.run.player.y),(40.,15.));assert_eq!(e.run.tick,tick+1.);assert!(e.dispatch(&Command::Move{dx:1.,dy:0.}).unwrap().took_turn);assert_eq!((e.run.player.x,e.run.player.y),(41.,15.));}
#[test]fn enemy_at_mate_is_attacked_before_transport(){let mut r=room();let id=rat(&mut r,40.,15.,false);r.player.conditions.insert("lucky".into(),1.);assert!(engine::move_actor(&mut r,0.,1.,0.,false).unwrap());assert_eq!((r.player.x,r.player.y),(8.,8.));assert!(engine::actor(&r,id).unwrap().hp<100.);assert_eq!((engine::actor(&r,id).unwrap().x,engine::actor(&r,id).unwrap().y),(40.,15.));}
#[test]fn ally_swap_and_nonattacking_occupancy_use_both_endpoints(){let mut r=room();let id=rat(&mut r,40.,15.,true);assert!(engine::move_actor(&mut r,0.,1.,0.,false).unwrap());assert_eq!((r.player.x,r.player.y),(40.,15.));assert_eq!((engine::actor(&r,id).unwrap().x,engine::actor(&r,id).unwrap().y),(8.,8.));let second=rat(&mut r,10.,8.,false);assert!(!engine::move_actor(&mut r,second,-1.,0.,true).unwrap());assert_eq!((engine::actor(&r,second).unwrap().x,engine::actor(&r,second).unwrap().y),(10.,8.));}
#[test]fn npc_path_uses_local_entry_step_and_remote_arrival(){let mut r=room();r.player.x=43.;r.player.y=15.;let id=rat(&mut r,8.,8.,false);let step=engine::creature_path_step(&mut r,id,Point{x:43,y:15}).unwrap();assert_eq!(step,Point{x:1,y:0});assert!(engine::move_actor(&mut r,id,step.x as f64,step.y as f64,true).unwrap());let a=engine::actor(&r,id).unwrap();assert_eq!((a.x,a.y),(40.,15.));}
#[test]fn directed_projectile_reaches_remote_actor_with_actual_range(){let mut r=room();divider(&mut r);let id=rat(&mut r,43.,15.,false);let p=projectiles::trace(&r,43.,15.);assert_eq!(p.actor_id,Some(id));assert!(projectiles::reaches_actor(&r,&p,engine::actor(&r,id).unwrap()));assert_eq!(projectiles::traveled_distance(&r,&r.player,43.,15.,&p),4.);let path=portals::aimed_ray(r.floor().unwrap(),Point{x:8,y:8},Point{x:43,y:15},|p|r.floor().unwrap().tiles[p.y as usize*79+p.x as usize]!="wall");assert!(path.windows(2).any(|w|w==[Point{x:9,y:8},Point{x:40,y:15}]));assert_eq!(path.last(),Some(&Point{x:43,y:15}));}
#[test]fn ray_stops_at_walls_before_entry_or_after_exit(){for before in [true,false]{let mut r=room();divider(&mut r);pair(&mut r,(10,8),(40,15));let id=rat(&mut r,43.,15.,false);if before{wall(&mut r,9,8)}else{wall(&mut r,41,15)}let p=projectiles::trace(&r,43.,15.);assert_ne!(p.actor_id,Some(id),"before={before}");}}
#[test]fn remote_endpoint_occupant_intercepts_without_duplicate_body(){let mut r=room();let id=rat(&mut r,40.,15.,false);let p=projectiles::trace(&r,9.,8.);assert_eq!(p.actor_id,Some(id));assert_eq!(r.actors_at(10.).iter().filter(|a|a.id==id).count(),1);assert_eq!(portals::actor_distance(&r,&r.player,engine::actor(&r,id).unwrap()),1.);}
#[test]fn optical_route_uses_remaining_distance_and_both_occlusions(){let mut r=room();divider(&mut r);let id=rat(&mut r,43.,15.,false);let target=engine::actor(&r,id).unwrap();assert!(vision::line_of_sight(&r,&r.player,target));assert_eq!(vision::optical_route(&r,&r.player,Point{x:43,y:15}).unwrap().distance,4.);wall(&mut r,41,15);assert!(!vision::line_of_sight(&r,&r.player,engine::actor(&r,id).unwrap()));}
#[test]fn multiple_portal_ray_cycle_is_bounded(){let mut r=room();let f=r.floor_mut().unwrap();f.portals=vec![PortalPair{a:8*79+9,b:8*79+20,color_index:0},PortalPair{a:8*79+21,b:8*79+8,color_index:1}].into();let p=portals::directed_ray(f,Point{x:8,y:8},Point{x:30,y:8},|_|true);assert!(p.len()<20);assert!(p.len()>=4);}
#[test]fn save_fixture_replay_and_temporal_restore_keep_pair_identity(){let mut r=room();r.player.abilities=vec!["numo-revert".into(),"morae-see-the-future".into()];r.player.conditions.insert("revertCharges".into(),5.);let initial=r.clone();let mut e=Engine::new(r).unwrap();for c in [Command::Move{dx:1.,dy:0.},Command::Move{dx:1.,dy:0.},Command::Wait]{e.dispatch(&c).unwrap();}let saved=e.save().unwrap();assert_eq!(Engine::load(&saved).unwrap().save().unwrap(),saved);let mut replay=ReplaySession::from_initial(initial,ReplayRecord::from_run(&e.run)).unwrap();while replay.step_with_outcome().unwrap().is_some(){}assert_eq!(replay.engine.save().unwrap(),e.save().unwrap());let pairs=e.run.floor().unwrap().portals.clone();assert!(e.dispatch(&ability("numo-revert")).unwrap().changed);assert_eq!(e.run.floor().unwrap().portals,pairs);}
#[test]fn dream_projection_crosses_same_plane_without_moving_sleeping_body(){let mut r=room();r.dreamwalking=dream::State{unlocked:true,..Default::default()}.into();dream::ability(&mut r,dream::DREAMWALK_ID).unwrap();let body=dream::body(&r).unwrap().id;let normal=rat(&mut r,40.,15.,false);assert!(engine::move_actor(&mut r,0.,1.,0.,false).unwrap());assert_eq!((r.player.x,r.player.y),(40.,15.));assert_eq!((engine::actor(&r,body).unwrap().x,engine::actor(&r,body).unwrap().y),(8.,8.));assert_eq!(engine::actor(&r,normal).unwrap().hp,100.);assert!(!dream::same_plane(&r,&r.player,engine::actor(&r,normal).unwrap()));}
#[test]fn half_here_has_native_plane_portal_view_and_alias_distance(){let mut r=room();r.player.abilities.push("etill-half-here".into());r.player.active.push("etill-half-here".into());let clone=half_here::create(&mut r,9.,8.).unwrap();let a=engine::actor(&r,clone).unwrap();assert!(portals::same_position(&r,a,40.,15.));assert_eq!(portals::point_distance(&r,a,43.,15.),3.);r.dreamwalking=dream::State{unlocked:true,..Default::default()}.into();dream::ability(&mut r,dream::DREAMWALK_ID).unwrap();let a=engine::actor(&r,clone).unwrap();assert!(!dream::dream_actor(&r,a));assert_eq!(portals::point_distance(&r,a,43.,15.),3.);}

#[test]fn future_branch_restores_player_and_linked_occupancy_after_crossing(){let mut r=room();r.player.abilities.push("morae-see-the-future".into());let initial=(r.player.x,r.player.y);let portals=r.floor().unwrap().portals.clone();let mut e=Engine::new(r).unwrap();assert!(e.dispatch(&ability("morae-see-the-future")).unwrap().changed);assert!(e.run.future.is_some());assert!(e.dispatch(&Command::Move{dx:1.,dy:0.}).unwrap().took_turn);assert_eq!((e.run.player.x,e.run.player.y),(40.,15.));e=Engine::load(&e.save().unwrap()).unwrap();assert!(e.dispatch(&ability("morae-see-the-future")).unwrap().changed);assert!(e.run.future.is_none());assert_eq!((e.run.player.x,e.run.player.y),initial);assert_eq!(e.run.floor().unwrap().portals,portals);}
#[test]fn actual_throw_attacks_remote_endpoint_and_empty_throw_lands_at_mate(){
 for occupied in [true,false]{let mut r=room();let id=if occupied{Some(rat(&mut r,40.,15.,false))}else{None};
  r.inventory.push(corpse_core::Item{id:900.,kind:"ammo".into(),name:"Arrow".into(),glyph:"→".into(),effect:"arrows".to_string().into(),quantity:1.0.into(),..Default::default()});r.player.conditions.insert("lucky".into(),1.);
  assert_eq!(projectiles::command(&mut r,&Command::Throw{id:900.,x:9.,y:8.}).unwrap(),Some(true));assert!(r.inventory.is_empty());let g=r.ground["10"].iter().find(|g|g.item.id==900.).unwrap();
  if let Some(id)=id{assert!(engine::actor(&r,id).unwrap().hp<100.,"actual Throw failed to damage endpoint occupant");}else{assert_eq!((g.x,g.y),(40.,15.));}
 }
}
#[test]fn underfoot_pickup_sees_the_other_endpoint_without_duplicate_items(){let mut r=room();r.player.x=40.;r.player.y=15.;r.ground_at_mut(10.).push(corpse_core::GroundItem{x:9.,y:8.,item:corpse_core::Item{id:901.,kind:"ammo".into(),name:"Arrow".into(),glyph:"→".into(),effect:"arrows".to_string().into(),quantity:1.0.into(),..Default::default()},..Default::default()});assert_eq!(corpse_core::inventory::collect_underfoot(&mut r,20.).unwrap(),1);assert!(r.ground["10"].is_empty());assert_eq!(r.inventory.iter().filter(|i|i.id==901.).count(),1);assert_eq!(corpse_core::inventory::collect_underfoot(&mut r,20.).unwrap(),0);}
#[test]fn projectile_range_without_portals_retains_legacy_euclidean_distance(){let mut r=room();r.floor_mut().unwrap().portals=Field::Missing;let p=projectiles::trace(&r,11.,10.);assert_eq!((p.x,p.y),(11.,10.));assert!((projectiles::traveled_distance(&r,&r.player,11.,10.,&p)-13f64.sqrt()).abs()<1e-12);}
#[test]fn diagonal_portal_projectile_preserves_direction_and_segment_range(){let mut r=room();divider(&mut r);pair(&mut r,(9,9),(40,15));let id=rat(&mut r,42.,17.,false);let p=projectiles::trace(&r,42.,17.);assert_eq!(p.actor_id,Some(id));assert!((projectiles::traveled_distance(&r,&r.player,42.,17.,&p)-3.*2f64.sqrt()).abs()<1e-12);}
#[test]fn no_portal_revision35_preserves_simple_revision34_command_results(){let mut current=room();current.floor_mut().unwrap().portals=Field::Missing;let mut old=current.clone();old.simulation_revision=34.0.into();for cmd in [Command::Move{dx:1.,dy:1.},Command::Wait,Command::Move{dx:-1.,dy:0.}]{let a=engine::dispatch(&mut old,&cmd).unwrap();let b=engine::dispatch(&mut current,&cmd).unwrap();assert_eq!(a.took_turn,b.took_turn);assert_eq!(old.player,current.player);assert_eq!(old.tick,current.tick);assert_eq!(old.rng,current.rng);assert_eq!(old.floors,current.floors);assert_eq!(old.actors,current.actors);}}
#[test]fn normal_enemy_can_melee_player_through_link_without_telefragging(){let mut r=room();r.player.x=40.;r.player.y=15.;r.player.stats.dodge=-1000.;let id=rat(&mut r,8.,8.,false);let a=engine::actor_mut(&mut r,id).unwrap();a.state="hunting".into();a.stats.offense=20.;a.stats.accuracy=10000.;a.conditions.insert("lucky".into(),1.);assert!(engine::dispatch(&mut r,&Command::Wait).unwrap().took_turn);assert!(r.player.hp<100.,"enemy never attacked through adjacent linked cell");assert_eq!((engine::actor(&r,id).unwrap().x,engine::actor(&r,id).unwrap().y),(8.,8.));}
#[test]fn forced_move_crosses_once_and_respects_remote_occupancy(){let mut r=room();r.player.conditions.insert("forcedMove".into(),1.);assert!(engine::move_actor(&mut r,0.,1.,0.,true).unwrap());assert_eq!((r.player.x,r.player.y),(40.,15.));let id=rat(&mut r,10.,8.,false);engine::actor_mut(&mut r,id).unwrap().conditions.insert("forcedMove".into(),1.);assert!(!engine::move_actor(&mut r,id,-1.,0.,true).unwrap());assert_eq!((engine::actor(&r,id).unwrap().x,engine::actor(&r,id).unwrap().y),(10.,8.));}
#[test]fn opaque_portal_endpoint_disables_optical_transfer_without_corrupting_save(){let mut r=room();divider(&mut r);let id=rat(&mut r,43.,15.,false);assert!(vision::line_of_sight(&r,&r.player,engine::actor(&r,id).unwrap()));wall(&mut r,40,15);assert!(!vision::line_of_sight(&r,&r.player,engine::actor(&r,id).unwrap()));assert_ne!(projectiles::trace(&r,43.,15.).actor_id,Some(id));let saved=corpse_core::storage::serialize(&r).unwrap();assert!(corpse_core::storage::deserialize(&saved).is_ok());}

#[test]fn direction_helper_preserves_zero_axes_and_portal_route_orientation(){
 let mut r=room();
 for revision in [1.,34.,35.] {
  r.simulation_revision=revision.into();r.floor_mut().unwrap().portals=Field::Missing;
  for (x,y,expected) in [(12.,8.,(1.,0.)),(4.,8.,(-1.,0.)),(8.,12.,(0.,1.)),(8.,4.,(0.,-1.)),(8.,8.,(0.,0.)),(12.,12.,(1.,1.))] {
   assert_eq!(portals::direction_toward(&r,&r.player,x,y),expected,"revision={revision} target=({x},{y})");
  }
 }
 pair(&mut r,(9,8),(40,15));assert_eq!(portals::direction_toward(&r,&r.player,43.,15.),(1.,0.));
 pair(&mut r,(8,9),(40,15));assert_eq!(portals::direction_toward(&r,&r.player,40.,18.),(0.,1.));
 pair(&mut r,(9,9),(40,15));assert_eq!(portals::direction_toward(&r,&r.player,42.,17.),(1.,1.));
 pair(&mut r,(8,8),(40,15));assert_eq!(portals::direction_toward(&r,&r.player,40.,15.),(0.,0.));
}
